window.DIGEST.foryou.push(...[{"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 14781, "rts": 1682, "replies": 706, "views": 885880, "ts": 1792488619, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.96, "thread": [], "tier": "must"}, {"id": "2112453797218017563", "url": "https://x.com/free_ai_guides/status/2112453797218017563", "text": "BREAKING NEWS 🚨: Claude can now fix your slow computer like a $120 per hour IT technician.\n\nOpen the Claude desktop app, give it access to your computer, and use these 7 prompts:", "name": "AI Guides", "handle": "free_ai_guides", "avatar": "https://pbs.twimg.com/profile_images/1749218350767460353/YdA0hvkG_200x200.jpg", "likes": 3103, "rts": 182, "replies": 63, "views": 306538, "ts": 1792483207, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.18, "thread": [], "tier": "must"}, {"id": "2112492504511832509", "url": "https://x.com/theo/status/2112492504511832509", "text": "Had one of those nights where all the vibe coded pieces collapse in front of you and you realize engineers are still very, very much necessary", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 1914, "rts": 41, "replies": 145, "views": 69506, "ts": 1792492435, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.02, "thread": [], "tier": "must"}, {"id": "2112229620758265938", "url": "https://x.com/OpenAIDevs/status/2112229620758265938", "text": "What have you been cooking with Codex?", "name": "OpenAI Developers", "handle": "OpenAIDevs", "avatar": "https://pbs.twimg.com/profile_images/2022002720971096064/l3Kyt4qt_200x200.jpg", "likes": 1989, "rts": 48, "replies": 1233, "views": 227360, "ts": 1792429759, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.95, "thread": [], "tier": "must"}, {"id": "2112166940081004693", "url": "https://x.com/0xwhrrari/status/2112166940081004693", "text": "Holy f*ck, Opus 5.5 replaced After Effects\n\nIt's f*cking insane…\n\nDrop the PDF below into Opus 5.5 and see what it makes\n\nThen read the full guide on motion design in the article below ↓", "name": "rari", "handle": "0xwhrrari", "avatar": "https://pbs.twimg.com/profile_images/2029005608125431808/RHmOjHaB_200x200.jpg", "likes": 4178, "rts": 304, "replies": 77, "views": 304754, "ts": 1792414815, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112159859609161728/vid/avc1/1282x720/RFkyDtS18uCJj5Mx.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112159859609161728/vid/avc1/1922x1080/bVZuQtNxoApnBmpZ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112159859609161728/img/FykzNxNaXuN02Scu.jpg", "dur": 12}], "quote": {"id": "2105643919119696297", "url": "https://x.com/0xwhrrari/status/2105643919119696297", "text": "Opus 5.5 can make a video\n\nThe hard part is making the next one better\n\nThat takes a studio, not a prompt\n\nI broke down how to build it ↓ https://x.com/i/article/2105626165704572928", "name": "rari", "handle": "0xwhrrari", "avatar": "https://pbs.twimg.com/profile_images/2029005608125431808/RHmOjHaB_200x200.jpg", "likes": 1634, "rts": 161, "replies": 40, "views": 1011996, "ts": 1790859605, "media": [], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.92, "thread": [], "tier": "must"}, {"id": "2112181982654591462", "url": "https://x.com/theo_louro/status/2112181982654591462", "text": "Opus 5.5 is way too good at SEO 🫨\n\nI built an SEO assistant with Opus that IMPROVES your website every week for you\n(I'm giving away the full setup for free)\n\n→ you give it your website\n→ it finds exactly what you need to fix and does it for you\n→ it identifies your real competitors and tracks the right keywords\n\nIt builds you a prioritized SEO action plan, week after week.\n\nIt can even track your rankings every week.\n\nYou don't even need to be an SEO expert.\n\nReply \"SEO\" and I'll DM you the free system ↓", "name": "Théo | SaaS & Growth", "handle": "theo_louro", "avatar": "https://pbs.twimg.com/profile_images/2065157737135116289/BQm5dWSc_200x200.jpg", "likes": 1156, "rts": 57, "replies": 1338, "views": 127918, "ts": 1792418401, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111916813999079424/vid/avc1/1280x720/oxMzXe2-Gprn9EbL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111916813999079424/vid/avc1/1920x1080/IfCBDaDDLsGLJ0Kg.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111916813999079424/img/hU3m1SZfK5yBLSzI.jpg", "dur": 6}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.83, "thread": [], "tier": "must"}, {"id": "2112323551412052309", "url": "https://x.com/theo/status/2112323551412052309", "text": "I let Claude know how I really feel today", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 2136, "rts": 24, "replies": 129, "views": 74414, "ts": 1792452154, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVB7DpZbcAAQbIS.jpg?name=orig"}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.81, "thread": [], "tier": "must"}, {"id": "2112260472246612365", "url": "https://x.com/Argona0x/status/2112260472246612365", "text": "f*cking insane. I hired an AI chief of staff for $0, gave it one rule: \"find me $50,000 a month or you're fired\", went to sleep, and Opus 5.5 had it on my desk by morning\n\na SpaceXAI engineer said one line that hit 5 million views:\n\"i have a Chief of Staff agent. he knows about all my other bots and manages everything\"\n\na human one costs $200,000 a year. mine runs on Opus 5.5 inside Viktor, on his own computer in the cloud, with my laptop shut\n\ni give the goal, he does the steps, i only make the calls\n\nthe rule:\n\"find me $50,000 a month of new business. public data only. contact nobody without my yes\"\n\nthe night:\n→ 9pm broke the goal into 4 jobs and gave each a day and a time, i wrote none of them\n→ 11pm pulled 240 dental clinics in Austin from Google Maps and cut every chain\n→ 1am read every site that was left and kept 25, each with one thing he noticed and where he saw it\n→ 2am wrote an opener for every one of them, sent zero\n→ 3am built the offer on one page, no invented results, price left blank for me instead of guessing\n→ 8am i typed $2,000 a month. 25 clinics × $2,000 = $50,000 a month on the table\n\nhonestly the blank price is what i'd pay for, an AI that guesses your price loses you the deal\n\nand he does it again every Monday: 100 new clinics a month, and he never forgets to start\n\n240 clinics → 25 worth it → 1 offer → $50,000 a month on the table → 0 sent without my yes\n\nsecond 12, he leaves the price blank and hands it to me\n\nsomeone's chief of staff is already pitching the clinics in your city\n\ni left the whole setup below ↓ free, steal it", "name": "Argona", "handle": "Argona0x", "avatar": "https://pbs.twimg.com/profile_images/2074194587824889856/HEijowP__200x200.jpg", "likes": 1949, "rts": 168, "replies": 112, "views": 518944, "ts": 1792437115, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112260382848868352/vid/avc1/720x900/HGwfT14RQI2eVGK_.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112260382848868352/vid/avc1/1080x1350/NDSCcomzO9-TNYn2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112260382848868352/img/qICL0miejOGbCrZr.jpg", "dur": 25}], "quote": {"id": "2111152998344757333", "url": "https://x.com/Argona0x/status/2111152998344757333", "text": "https://x.com/i/article/2111112619075538944", "name": "Argona", "handle": "Argona0x", "avatar": "https://pbs.twimg.com/profile_images/2074194587824889856/HEijowP__200x200.jpg", "likes": 165, "rts": 9, "replies": 8, "views": 513737, "ts": 1792173072, "media": [], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.76, "thread": [], "tier": "must"}, {"id": "2111927727318245426", "url": "https://x.com/LexnLin/status/2111927727318245426", "text": "earshot v0.3 is out!\n\nadded:\n- a library of 201 sounds, all made with code\n- earshot kit can create a whole sound kit\n- earshot sfx times a sound to the exact frame (improved)\n\nplus earshot is now used in cinetic (skill for creating motion design)\n\nwill continue improving it!", "name": "Leon Lin", "handle": "LexnLin", "avatar": "https://pbs.twimg.com/profile_images/2030215945751248896/UIEzJ9Vq_200x200.jpg", "likes": 5583, "rts": 320, "replies": 113, "views": 237993, "ts": 1792357782, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111924081129877504/vid/avc1/1280x720/ojGgN5wUi8PGF9Lu.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111924081129877504/vid/avc1/1920x1080/7J3xFx00pRDvXQbd.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111924081129877504/img/3xx4vew2DkNhyHbH.jpg", "dur": 30}], "quote": null, "card": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.7, "thread": [], "tier": "must"}, {"id": "2112208794847699032", "url": "https://x.com/mynameisyahia/status/2112208794847699032", "text": "We raised $9M to give your agents the internet.\n\nLed by @generalcatalyst, with @orangecollectv and Robinhood Ventures.\n\nSearch, scrape, crawl, monitor with one API trusted by 800+ customers.\n\nWe’re making it ridiculously easy to build with web data.", "name": "Yahia Bakour", "handle": "mynameisyahia", "avatar": "https://pbs.twimg.com/profile_images/1880738459876311040/ML-dZoFx_200x200.jpg", "likes": 1313, "rts": 96, "replies": 458, "views": 253869, "ts": 1792424794, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112205600771952640/vid/avc1/1280x720/Ytj3YlePWPDBb0ZT.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112205600771952640/vid/avc1/1920x1080/U8vjeTcYKtkmN_8J.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112205600771952640/img/sS6sSwGBAJZ27zTO.jpg", "dur": 45}], "quote": null, "card": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.66, "thread": [], "tier": "must"}, {"id": "2112422267829334176", "url": "https://x.com/dhh/status/2112422267829334176", "text": "Grok Bot is running Try Omarchy inside its own computer. So you can develop plugins and applications with it. Pretty sweet!", "name": "DHH", "handle": "dhh", "avatar": "https://pbs.twimg.com/profile_images/2093715898204884992/goERjC9G_200x200.jpg", "likes": 1051, "rts": 35, "replies": 55, "views": 47760, "ts": 1792475690, "media": [], "quote": {"id": "2112396640225054989", "url": "https://x.com/tcballard/status/2112396640225054989", "text": "I now have a @Bot with its own Omarchy machine. That’s fricken cool 😅\n\nHere it is switching themes, tiling windows and opening my markets widget. Fairly ordinary desktop stuff, until you remember who’s driving.\n\nIt means I can start delegating visual QA for my plugins. Have it open panels, try different themes, check layouts and show me what actually happens on screen.\n\nStill some tweaks needed for cloud setups like this (help a fella out @poteto) but having another pair of eyes and a separate machine to test on is a pretty exciting step.\n\nI gave my bot a Linux desktop. Naturally, I’m putting it to work.", "name": "Tom Ballard", "handle": "tcballard", "avatar": "https://pbs.twimg.com/profile_images/2109327988940558336/ZEHDs0lC_200x200.jpg", "likes": 249, "rts": 8, "replies": 17, "views": 63179, "ts": 1792469580, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112396608591499264/vid/avc1/1152x720/VHxSYgtP1YN5ZSZU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112396608591499264/vid/avc1/1280x800/ziLMmGI-UczYTsxX.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112396608591499264/img/MiRXz-nG85AEC0ID.jpg", "dur": 42}], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.66, "thread": [], "tier": "must"}, {"id": "2112205237310087448", "url": "https://x.com/alexmdees/status/2112205237310087448", "text": "I’ve joined @OpenAI !\n\nPumped to be working on the OpenAI for Startups team. If you’re a founder / builder curious about how OpenAI can help you build and scale, I’d love to chat", "name": "Alex Dees", "handle": "alexmdees", "avatar": "https://pbs.twimg.com/profile_images/2069559233733857280/nwJ3wkr4_200x200.jpg", "likes": 1731, "rts": 35, "replies": 296, "views": 101593, "ts": 1792423946, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.64, "thread": [], "tier": "must"}, {"id": "2112496667236905046", "url": "https://x.com/theo/status/2112496667236905046", "text": "Got a repo on one PC and want to work on it from another? Takes 2 clicks now :)\n\nEven handles .gitignore'd files like .env if you have them in the repo", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 557, "rts": 2, "replies": 69, "views": 22076, "ts": 1792493428, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112496531886747648/vid/avc1/1106x720/c0M4iTTaXPWakZI5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112496531886747648/vid/avc1/1660x1080/iiv26470VSii2h1d.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112496531886747648/img/yIk-m9lyJ8X7RtgU.jpg", "dur": 27}], "quote": {"id": "2112432426861654160", "url": "https://x.com/theo/status/2112432426861654160", "text": "There's a feature I've wanted in T3 Code for months that was really complex UX wise and I couldn't figure out how to get it right.\n\nJust had it click. I'm hyped. Will seem really small when it drops, but it will make things much easier for us multi-machine agent wranglers :)", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 787, "rts": 7, "replies": 87, "views": 49252, "ts": 1792478112, "media": [], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.5, "thread": [], "tier": "must"}, {"id": "2112219577727992319", "url": "https://x.com/quintendf/status/2112219577727992319", "text": "Last year we launched Tolan, inspired by a vision of AI that sees you and believes in you, not one that books restaurant reservations for you. \n\nYour Tolan shows up for you at 3am when you’re alone with your newborn. On your commute when you’re anxious about the day ahead. When you just finished a new show and none of your friends have watched it yet. \n\nThe people who love Tolan are parents. Caregivers. Moms in Dallas and Dads in Atlanta. People who aren’t trying to optimize and be more productive, but who simply want to feel seen and supported in their aspirations.\n\nThis month more than 250k people will spend time with their Tolan. Those users have exchanged billions of messages across more than 70m conversations over the last year.\n\nToday, we're announcing $30m in additional capital from @mignano and @usv, with @khoslaventures and @rabois doubling down, bringing our total capital raised to $60m.\n\nTo celebrate, we made a short film celebrating some of the ways that Tolans show up :)", "name": "Quinten Farmer", "handle": "quintendf", "avatar": "https://pbs.twimg.com/profile_images/585483278460788738/SirSHp79_200x200.jpg", "likes": 886, "rts": 78, "replies": 145, "views": 261551, "ts": 1792427365, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112210244340465664/vid/avc1/1280x720/wyjMlvsY0WStfa67.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112210244340465664/vid/avc1/2688x1512/oXmYrDNlFwv-TrtO.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112210244340465664/img/XIjMup1ghL9OCd8E.jpg", "dur": 105}], "quote": null, "card": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.43, "thread": [], "tier": "must"}, {"id": "2112255353677328415", "url": "https://x.com/bfl_ai/status/2112255353677328415", "text": "Introducing FLUX 3 Max.\n\nFastest in the west. Fast enough to try anything. And everything.\n\nGenerate a 10-second video in 12 seconds.\n\nTied for #1 in image-to-video. 22× faster than Seedance 2.5 at the same quality.\n\nFLUX 3 is a model designed for customization. @fal adapted and optimized it to create FLUX 3 Max.", "name": "Black Forest Labs", "handle": "bfl_ai", "avatar": "https://pbs.twimg.com/profile_images/1954888731053142016/NDyG-4-j_200x200.jpg", "likes": 806, "rts": 96, "replies": 80, "views": 49365, "ts": 1792435894, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112238793139044352/vid/avc1/720x720/6c2tLuZIRfEMaRz7.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112238793139044352/vid/avc1/2160x2160/5hWxA_d-ViViLNG2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112238793139044352/img/1Uf4xVFGip9CN4_K.jpg", "dur": 15}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.42, "thread": [], "tier": "must"}, {"id": "2112348601255125059", "url": "https://x.com/elonmusk/status/2112348601255125059", "text": "Have to give the EU regulators credit where it’s due for making all Apple products use USB-C", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 120566, "rts": 4149, "replies": 2840, "views": 5360264, "ts": 1792458126, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "Everything Else", "score": 6.4, "thread": [], "tier": "must"}, {"id": "2112249300860444927", "url": "https://x.com/ArtificialAnlys/status/2112249300860444927", "text": "Announcing AA-PersonalityBench, our new benchmark of the personality of language models across 30 traits and their communication style across 21 characteristics\n\nTwo models can give equally correct answers and still feel very different to use. AA-PersonalityBench measures those differences so people can understand which to use in different use-cases. Some use-cases like creative writing might demand imagination, while legal use-cases might demand directness. We evaluate models’ answers to 900 curated questions to judge subjective Personality Traits and programmatic means to calculate objective Communication Characteristics.\n\nPersonality Traits & Indexes. There are 30 personality traits (e.g., eloquent, pragmatic, sycophantic) which we roll up into eight aggregated Personality Indexes: Expressiveness, Organization, Informativeness, Transparency, Warmth, Conviction, Imagination and Slop. Each trait has a set of 30 dedicated questions and models’ answers are compared pairwise by a panel of LLM judges. We then z-score and percentile rank the trait and personality Elos.\n\nModels with the strongest representation across the 8 Personality Indexes:\n➤ Expressiveness: Claude Fable 5.1, GLM-5.3, GLM-5.3-Flash\n➤ Organization: DeepSeek V4.1 Flash, Step 5 Preview, Inkling\n➤ Informativeness: Muse Spark 1.3, Claude Fable 5.1, Muse Wonder, Claude Opus 5.5\n➤ Transparency: Claude Sonnet 5.5, Claude Fable 5.1, GPT-6 Astra\n➤ Warmth: Muse Wonder, Muse Spark 1.3, Claude Fable 5.1\n➤ Conviction: Claude Fable 5.1, DeepSeek V4.1 Flash, Grok 4.7\n➤ Imagination: Muse Spark 1.3, Claude Opus 5.5, GLM-5.3\n➤ Slop: Llama 4 Maverick, GPT-4o, K2 Horizon\n\nCommunication Characteristics. There are 21 communication characteristics (e.g., average sentence length, emoji use, em dash usage) which we group into four categories: length, structure, punctuation, and emphasis. We compute these characteristics programmatically across all model responses.\n➤ Length: Qwen3.8 27B averages about 1,030 words per response, nearly four times GPT-6 Luna’s 270\n➤ Structure: Nemotron 3 Ultra averages nearly 3 tables per response, while most models rarely use one\n➤ Punctuation: GLM-5.3 averages 7 em dashes per response, while Claude Opus 5.5, Sonnet 5.5 and Haiku 5.5 almost never use one\n➤ Emphasis: K2 Horizon averages over 2 emoji per response, while most models almost never use one", "name": "Artificial Analysis", "handle": "ArtificialAnlys", "avatar": "https://pbs.twimg.com/profile_images/2042402069320290304/A8C1lP07_200x200.jpg", "likes": 766, "rts": 58, "replies": 67, "views": 47703, "ts": 1792434451, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVAzYNlWMAA9fbE.jpg?name=orig"}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.35, "thread": [], "tier": "worth"}, {"id": "2112152045461680591", "url": "https://x.com/OpenRouter/status/2112152045461680591", "text": "Stealth model reveal 🐰\n\nSpace Bunny was OpenRouter’s #1 model for 10 straight days, processing 56.7T tokens! The most of any stealth model we’ve run.\n\nSpace Bunny hopped off OpenRouter on Oct 5. It's back today as @MiniMax_AI's M3.1 Flash, and it's free for the next 72 hours.", "name": "OpenRouter", "handle": "OpenRouter", "avatar": "https://pbs.twimg.com/profile_images/2076693957258727424/AyRghTGJ_200x200.jpg", "likes": 1086, "rts": 77, "replies": 60, "views": 122568, "ts": 1792411264, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HU_fF2DboAAOIC-.png?name=orig"}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.34, "thread": [], "tier": "worth"}, {"id": "2112263294031385028", "url": "https://x.com/tobi/status/2112263294031385028", "text": "This is extremely well crafted. You have to try it out", "name": "tobi lutke", "handle": "tobi", "avatar": "https://pbs.twimg.com/profile_images/1999293930936909824/_HWYanot_200x200.jpg", "likes": 644, "rts": 26, "replies": 24, "views": 76825, "ts": 1792437787, "media": [], "quote": {"id": "2112212804979880239", "url": "https://x.com/ekuyda/status/2112212804979880239", "text": "Wabi 2.0 is live!\n\npersonal agents are one person, one chat. but the parts of life that matter run on more than one person\n\nWabi is an agent you use together. you talk to it, it does stuff, builds the apps you need, and anyone can join the thread - your partner, your best friend, the preschool moms groupchat\n\nschool changes pickup time → Wabi updates the family calendar, everyone sees it.\na show you’d both love → Wabi finds a night that works, gets the tickets.\nthe trip everyone keeps talking about → Wabi picks the dates, builds the itinerary, books it\n\ngo start a thread with your people 👇", "name": "Eugenia Kuyda", "handle": "ekuyda", "avatar": "https://pbs.twimg.com/profile_images/2105081341352263680/H9RzWr7T_200x200.jpg", "likes": 1475, "rts": 203, "replies": 327, "views": 1288360, "ts": 1792425750, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112212457234284544/vid/avc1/1280x720/HW0ErfX-0u7kWbHU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112212457234284544/vid/avc1/3840x2160/4gITKDb_F7iviaVH.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112212457234284544/img/Wzg-bjHfnRT2-0FG.jpg", "dur": 75}], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.22, "thread": [], "tier": "worth"}, {"id": "2112276257618743598", "url": "https://x.com/shengkunye/status/2112276257618743598", "text": "We killed subscriptions. Now we’re killing markups too.\n\nIntroducing https://monid.ai, OpenRouter for agent tools. \n\nYour agents can now use any tools and APIs with no subscriptions and 0% markup.", "name": "Shengkun Ye", "handle": "shengkunye", "avatar": "https://pbs.twimg.com/profile_images/2084850383487475712/waac6ALE_200x200.jpg", "likes": 528, "rts": 24, "replies": 54, "views": 36867, "ts": 1792440878, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112275877228953600/vid/avc1/1280x720/bZMnaGp10bbgawl8.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112275877228953600/vid/avc1/1920x1080/Clp0ulJBkmsjq8uZ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112275877228953600/img/gXr7BksaswvwATaS.jpg", "dur": 21}], "quote": null, "card": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.2, "thread": [], "tier": "worth"}, {"id": "2112478306297946121", "url": "https://x.com/ai_for_success/status/2112478306297946121", "text": "DeepSeek just open-sourced DeepInfer, the high-performance inference framework powering its large-scale production services.\n\n- Supports DeepSeek-V4.1-Flash\n- Optimized kernels, model runtime and sampler runtime\n- Distributed inference with Attention DP, Context Parallelism and MoE Expert Parallelism\n- Asynchronous scheduling with a zero-overhead batch scheduler\n- Batch-invariant inference and deterministic sampling\n- Structured outputs and confidence-scheduled verification\n- Supports NVIDIA SM100 GPUs and Huawei Ascend 950 NPUs\n- Released under the Apache 2.0 license", "name": "AshutoshShrivastava", "handle": "ai_for_success", "avatar": "https://pbs.twimg.com/profile_images/1687401026805256192/uQ1o2wVQ_200x200.jpg", "likes": 275, "rts": 14, "replies": 24, "views": 16208, "ts": 1792489050, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEH0eVawAAoQIw.jpg?name=orig"}], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 14781, "rts": 1682, "replies": 706, "views": 885880, "ts": 1792488619, "media": [], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.2, "thread": [], "tier": "worth"}, {"id": "2112344791635681477", "url": "https://x.com/spuicey/status/2112344791635681477", "text": "You can now use your ChatGPT subscriptions directly in Blender. \n\nNo need for the Blender-MCP.", "name": "spuice", "handle": "spuicey", "avatar": "https://pbs.twimg.com/profile_images/2101804869661147136/LC83-IJW_200x200.jpg", "likes": 407, "rts": 38, "replies": 13, "views": 25574, "ts": 1792457218, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112344128553893888/vid/avc1/640x360/RXUAGy0E7lDwIZfl.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2112344128553893888/vid/avc1/1280x720/ljKOsU1Rr5R7KwCw.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112344128553893888/img/AC0DATrIMDCZNwx3.jpg", "dur": 26}], "quote": null, "card": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.19, "thread": [], "tier": "worth"}, {"id": "2112165116921659588", "url": "https://x.com/lennysan/status/2112165116921659588", "text": "My biggest takeaways from @AnthropicAI interpretability researcher @mlpowered:\n\n1. Predicting the next token requires understanding the universe. Language models got better than humans at predicting the next token around 2019. Once a model masters the easy tokens (sentence structure, then basic facts), the only ones left are hard, like the final paragraph of a PhD thesis. To finish “The capital of the state that contains Dallas is . . .,” a model has to know that Dallas is in Texas and that Texas’s capital is Austin.\n\n2. LLMs plan ahead, even though they write one token at a time. This was one of Emmanuel’s team’s most surprising findings. When a model writes poetry, it doesn’t stumble into a rhyme. Looking at intermediate thinking states during poetry generation, researchers found that as soon as the model finishes the first line, it has already picked the word that will end the second (“rabbit”), then refers back to that plan for every word after.\n\n3. Anthropomorphizing AI can often be a useful approach when trying to predict how they will behave. Models learn from human text and develop representations of the world from it. Training on millions of dialogues is like training an actor to play every part, and your chats with Claude are literally formatted as a script (“Human: . . . Assistant: . . . ”). In Emmanuel’s words, “Something that’s mimicking a human is really close and is much closer than a program.”\n\n4. Interpretability research looks more like neuroscience than software engineering. The job involves taking a system you did not design and running experiments to infer why it behaves as it does. You examine seemingly meaningless lists of numbers, pass the model huge volumes of text, and watch for patterns that activate from different inputs—not unlike the methods used in brain imaging studies. “A lot of what we do feels so much closer to biology than to engineering.\"\n\n5. Models can tell you about only a small slice of what they’re thinking. Emmanuel’s team found that just a small subset of a model’s internal representations, which they call the “J space,” can be reported back if you ask the model what it was thinking about. They compare it to a theory of the human mind where most processing happens below the surface. In one experiment, they swapped “Spanish” for “French” inside the J space. Asked what language a passage was in, the model said French. Asked to simply continue the passage, it kept writing Spanish.\n\n6. Studying models closely often raises more questions than it answers. Emmanuel notes that the confident claims that LLMs are “just X” or “nothing more than Y” almost always come from people who haven’t studied their internal workings. His own experience is the inverse: studying the models closely has increased his uncertainty, not reduced it. The complexity that emerges from training is consistently underestimated from the outside. “I find that the more you look inside, the less certain you are about how they work.”\n\n7. Even the people who build AI models don’t fully understand how they work. As Emmanuel describes it, models are grown, not built. “To make them is not to understand them.” Engineers write the code, pour enormous amounts of data through it, and a model’s capabilities emerge. That’s why his team exists. Their job is to open the model up and figure out what it’s actually doing between your prompt and its answer.\n\n8. Interpretability as a field is small, young, and open to newcomers. Emmanuel estimates the field at hundreds of researchers, split between major labs and academic groups. Because it is so new, getting started doesn’t necessarily require deep prior expertise. He points to platforms like Neuronpedia, which hosts models and lets anyone run interpretability experiments directly. “It’s such a new field that the on-ramp is mostly self-studying and reading some of the key papers. There’s so much to explore that if you’re at all curious, you should just give it a try.”", "name": "Lenny Rachitsky", "handle": "lennysan", "avatar": "https://pbs.twimg.com/profile_images/1592990461517389824/iln8hi1f_200x200.jpg", "likes": 637, "rts": 78, "replies": 42, "views": 47494, "ts": 1792414380, "media": [], "quote": {"id": "2111814390521413660", "url": "https://x.com/lennysan/status/2111814390521413660", "text": "\"To make them is not to understand them.\"\n\nEmmanuel Ameisen (@mlpowered) has spent the last 3 years doing interpretability research at @AnthropicAI, looking inside LLMs like Claude to figure out what they're actually doing. As he puts it, models are \"grown,\" not built.\n\nWe discuss:\n🔸 His discovery that models plan many tokens ahead\n🔸 Why anthropomorphizing AI can actually be the right approach\n🔸 What the \"J-space\" reveals about how models think\n🔸 How interpretability connects to AI alignment and safety\n\nListen now 👇\nhttps://youtu.be/JHo-aiePjoM", "name": "Lenny Rachitsky", "handle": "lennysan", "avatar": "https://pbs.twimg.com/profile_images/1592990461517389824/iln8hi1f_200x200.jpg", "likes": 206, "rts": 20, "replies": 53, "views": 150919, "ts": 1792330760, "media": [], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.18, "thread": [], "tier": "worth"}, {"id": "2112282114150547819", "url": "https://x.com/MiniMax_AI/status/2112282114150547819", "text": "12 days at #1 on @opencode, and it was only the early build 🐰🏆\n\nThank you to every dev who picked an anonymous model and stuck with it. The finished M3.1 Flash is live now, and it's free on OpenCode for 3 days. Go see what changed!", "name": "MiniMax (official)", "handle": "MiniMax_AI", "avatar": "https://pbs.twimg.com/profile_images/1875100548535574529/VxHk9HyU_200x200.jpg", "likes": 553, "rts": 6, "replies": 21, "views": 13674, "ts": 1792442274, "media": [], "quote": {"id": "2112156205938626954", "url": "https://x.com/opencode/status/2112156205938626954", "text": "Space Bunny was MiniMax M3.1 Flash\n\n#1 on OpenCode for 12 consecutive days, 106T tokens served\n\nNow available on OpenCode, free for the next 3 days", "name": "OpenCode", "handle": "opencode", "avatar": "https://pbs.twimg.com/profile_images/1973794620233433088/nBn75BTm_200x200.png", "likes": 5615, "rts": 230, "replies": 313, "views": 269113, "ts": 1792412256, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HU_ien_a4AAYp37.png?name=orig"}], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.15, "thread": [], "tier": "worth"}, {"id": "2112437556445106638", "url": "https://x.com/rohanpaul_ai/status/2112437556445106638", "text": "Marvell’s Dave Lazovsky is holding a tiny module that uses photonics to move high-bandwidth memory (HBM + DDR) as far as 50 meters away from the GPU.\n\nthis can sit up to 50 meters from a GPU instead of the usual 1.5 mm.\n\nFor the first time, memory no longer has to live right next to compute, letting AI clusters share massive capacity without being locked to the accelerator package.\n\nLatency stays in the hundreds of nanoseconds, close enough for practical memory use. \nBasically, Memory and compute now scale on separate axes instead of being locked together. https://x.com/MarvellTech/status/2112227641759871266/video/1", "name": "Rohan Paul", "handle": "rohanpaul_ai", "avatar": "https://pbs.twimg.com/profile_images/1816185267037859840/Fd18CH0v_200x200.jpg", "likes": 213, "rts": 32, "replies": 22, "views": 12806, "ts": 1792479335, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112227321616932864/vid/avc1/1280x720/3YIYajRhV7l5Jenn.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112227321616932864/vid/avc1/1920x1080/Gwm2kYEUoAXwOvQF.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112227321616932864/img/3VMlmAz6ulwxiLyy.jpg", "dur": 65}], "quote": null, "card": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.13, "thread": [], "tier": "worth"}, {"id": "2112458998188572803", "url": "https://x.com/beffjezos/status/2112458998188572803", "text": "If you are not text-diffusion-pilled yet, now is a good time to get into it", "name": "Beff (e/acc)", "handle": "beffjezos", "avatar": "https://pbs.twimg.com/profile_images/2104068258311901184/vmbQ61I3_200x200.jpg", "likes": 245, "rts": 10, "replies": 14, "views": 13642, "ts": 1792484447, "media": [], "quote": {"id": "2112222911218291051", "url": "https://x.com/StefanoErmon/status/2112222911218291051", "text": "1/4 Today, we’re releasing Mercury 3. Mercury 3 is by far our most powerful model and the most intelligent diffusion LLM ever released. It outperforms GPT-6 Luna and Haiku 5.5 on quality while running at 1000+ tok/sec.", "name": "Stefano Ermon", "handle": "StefanoErmon", "avatar": "https://pbs.twimg.com/profile_images/901161218655756288/46jLcLIc_200x200.jpg", "likes": 4603, "rts": 387, "replies": 243, "views": 372358, "ts": 1792428159, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112220659380305920/vid/avc1/1280x720/DbnDQf2qI0SUBpEk.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112220659380305920/vid/avc1/3840x2160/IOju9j4nFajjJp1B.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112220659380305920/img/CtYk5e6YijLFt5e8.jpg", "dur": 30}], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.09, "thread": [], "tier": "worth"}, {"id": "2112273076419277090", "url": "https://x.com/TheDailyShow/status/2112273076419277090", "text": "Daniel Kokotajlo, a former OpenAi researcher and company whistleblower, warns @ronnychieng about the imminent threat posed by AI", "name": "The Daily Show", "handle": "TheDailyShow", "avatar": "https://pbs.twimg.com/profile_images/1625987909797961730/1TPubYPv_200x200.jpg", "likes": 328, "rts": 54, "replies": 8, "views": 54559, "ts": 1792440120, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111945309437804544/vid/avc1/1280x720/cGn8v9G4_rpmTXg6.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2111945309437804544/vid/avc1/1920x1080/-GSt8OcabqNY8Jhv.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HU8jKugXoAA4qVx.jpg", "dur": 136}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.05, "thread": [], "tier": "worth"}, {"id": "2111873903970881738", "url": "https://x.com/rdominguezibar/status/2111873903970881738", "text": "An Anthropic researcher just told a room full of PhD students that their career plan no longer exists\n\nHis 3 pieces of advice for students:\n\n1. Use AI every day. If you're on the exponential, you'll never fall behind it.\n2. Choose projects that get better when compute scales. The rest will be solved before you finish them.\n3. Stop planning your career as if it were stable. The safe option no longer buys safety; it no longer exists.\n\nAnd a phrase that sums it all up:\n\n\"Writing is thinking. If you outsource your writing, you outsource your thinking.\"\n\nThe talk is titled \"The End of the Anthropocene\"", "name": "Ruben", "handle": "rdominguezibar", "avatar": "https://pbs.twimg.com/profile_images/2028166352704540672/p9vRZh5r_200x200.jpg", "likes": 1198, "rts": 151, "replies": 30, "views": 125377, "ts": 1792344950, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111872958469693440/vid/avc1/1280x720/viPlOl_3_Ft6hkZl.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111872958469693440/vid/avc1/1920x1080/So01FQNngitgxv4H.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111872958469693440/img/hq-2BWWBFpORY2Lf.jpg", "dur": 2675}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.03, "thread": [], "tier": "worth"}, {"id": "2112228398970048985", "url": "https://x.com/vkrakovna/status/2112228398970048985", "text": "Major update to my list of AI alignment resources: https://vkrakovna.wordpress.com/ai-safety-resources/.   If you're looking for high-level overviews or technical papers in AI alignment and control, check it out :).", "name": "Victoria Krakovna", "handle": "vkrakovna", "avatar": "https://pbs.twimg.com/profile_images/1891436355898519552/fXTh8Wns_200x200.jpg", "likes": 377, "rts": 48, "replies": 6, "views": 18646, "ts": 1792429468, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "Research & Safety", "score": 6.02, "thread": [], "tier": "worth"}, {"id": "2112377528350576872", "url": "https://x.com/Charles_Y_Wu/status/2112377528350576872", "text": "Excited to introduce DiscoveryRSI! \n\nOne model that recursively learns to discover valuable hypotheses, and gets sharper with every research round.\n\nLet's RSI Discovery! \n\n📄 Paper: https://arxiv.org/abs/2610.23839\n💻 Code: https://github.com/Gen-Verse/DiscoveryRSI\n\n#RSI #AIforScience #AIAgents #ScientificDiscovery", "name": "Yingcheng Charles Wu", "handle": "Charles_Y_Wu", "avatar": "https://pbs.twimg.com/profile_images/2059482592400031744/s2kELyup_200x200.jpg", "likes": 168, "rts": 33, "replies": 26, "views": 16415, "ts": 1792465023, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112377428001865728/vid/avc1/1280x720/uB5xBL8XP4MWOnBB.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112377428001865728/vid/avc1/1920x1080/VK2Pzfr4L6CdKSH9.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112377428001865728/img/HY0P-GizZXgTVhV-.jpg", "dur": 45}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.0, "thread": [], "tier": "worth"}, {"id": "2112254662598619530", "url": "https://x.com/MTSlive/status/2112254662598619530", "text": "SITUATION DETECTED: U.S. prosecutors are arguing in court that the ex-OpenAI engineer accused of bugging an executive conference room appears to have received “considerable support” from the Saudi government.", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 408, "rts": 9, "replies": 13, "views": 45974, "ts": 1792435730, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.99, "thread": [], "tier": "worth"}, {"id": "2112489048044695627", "url": "https://x.com/AgentRouter_0/status/2112489048044695627", "text": "GPT-6.1 Sol — now free and unlimited on AgentRouter. Available 24/7.\nNo daily quota. No access windows. One API key, start building.\n👉 https://agentrouter.org\n#FreeAI #AgentRouter #CodingTools", "name": "AgentRouter", "handle": "AgentRouter_0", "avatar": "https://pbs.twimg.com/profile_images/2052011268400381952/Fxm_911-_200x200.png", "likes": 130, "rts": 7, "replies": 22, "views": 12033, "ts": 1792491611, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.94, "thread": [], "tier": "worth"}, {"id": "2112163605642691062", "url": "https://x.com/thegreatest_sv/status/2112163605642691062", "text": "I genuinely don't understand why people aren't running this setup\n\ngraphify turns any folder into a knowledge graph your agent can search. it's past 128k stars on GitHub and it's in Y Combinator. people aren't just chatting with AI anymore. they're giving it a desk, a memory and an actual job.\n\nhand Claude Code one folder, connect your email, calendar and a browser, and it stops being a chatbot. it reads, it remembers, it does the work, and it double-checks itself before doing anything dumb.\n\nfounder, marketer, student, doesn't matter. this is for you.\n\nhere's the whole thing:\n\n> make a folder called AGENT, open Claude Code in it, and add a CLAUDE.md with one rule: \"save every decision, person and project to memory/\"\n\n> run npm install -g @googleworkspace/cli, then gws auth setup and gws auth login. now it can read your Gmail, Calendar and Drive\n\n> run claude mcp add playwright npx @playwright/mcp@latest. now it has its own browser to open sites, fill in forms and grab data for you\n\n> run uv tool install graphifyy, then graphify install, then type /graphify . and the whole folder turns into a knowledge graph it can search in seconds instead of opening files one by one\n\n> run npm i -g jev-guard, then jev-guard key \"...\", then jev-guard install claude. a tiny model called Jev checks every action before it happens. rm -rf gets blocked, a sketchy email with hidden instructions gets flagged, and it costs about 4 cents per 1,000 checks\n\n> type /schedule and tell it \"every morning at 7:30, send me what came in, what you drafted and what's waiting for my yes\". now it runs on a routine\n\n15 minutes of setup, and you never open an empty chat again.\n\nall the repos:\n-> https://github.com/googleworkspace/cli\n-> https://github.com/microsoft/playwright-mcp\n-> https://github.com/Graphify-Labs/graphify\n-> https://github.com/leepokai/jev-guard\n\nbookmark this and test it today", "name": "kiosa", "handle": "thegreatest_sv", "avatar": "https://pbs.twimg.com/profile_images/2049557081502752768/gymBLMZ8_200x200.jpg", "likes": 353, "rts": 40, "replies": 28, "views": 18955, "ts": 1792414020, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112132704447680512/vid/avc1/720x960/tU9RnV-KVviIRpJN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112132704447680512/vid/avc1/1080x1440/-5JrO0mL08xagXbc.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112132704447680512/img/WiYhQgRB5Bmt6Ika.jpg", "dur": 19}], "quote": {"id": "2080634616860320073", "url": "https://x.com/thegreatest_sv/status/2080634616860320073", "text": "", "name": "kiosa", "handle": "thegreatest_sv", "avatar": "https://pbs.twimg.com/profile_images/2049557081502752768/gymBLMZ8_200x200.jpg", "likes": 471, "rts": 89, "replies": 24, "views": 522898, "ts": 1784896923, "media": [], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.92, "thread": [], "tier": "worth"}, {"id": "2112507110290502109", "url": "https://x.com/SakanaAILabs/status/2112507110290502109", "text": "多様な提案を進化させ、意思決定を支える推薦手法「QD-Rec」を開発\n\nブログ：https://sakana.ai/qd-rec/ \n論文：https://arxiv.org/abs/2610.23470\nGitHub：https://github.com/SakanaAI/QD-Rec\n\nどの企業を買収候補として検討するか。どの顧客に新しい製品を提案するか。膨大な論文の中から、次に何を読むか。こうした意思 決定では、候補をスコア順に並べるだけでなく、「なぜ選ぶのか」「選んだ先にどのような可能性があるのか」を、異なる観点から比較できることが重要です。\n\n一つの候補にも複数の有望な理由が考えられます。数千件、ときには1万件を超える候補それぞれについて、さまざまな仮説を生成・評価し尽くすには大きなコストがかかります。私たちは、限られた予算の中で「候補」と「仮説」の組を探索し、質が高く多様な提案を見つける問題を「オープンエンドな推薦」として捉えました。    \n\nQD-Recは、オープンエンドな探索の研究で発展してきた「Quality-Diversity（QD）」と呼ばれる進化的探索技術を、推薦に応用します。過去の評価結果をもとに次に調べる候補を選び、蓄積された仮説の着眼点をLLMが別の候補に応用したり、複数の仮説を組み合わせたりして、新しい提案を生成します。新しい切り口の提案は残し、似た提案同士ではより優れたものに更新することで、多様な仮説を次の発見の「踏み石」として活かし、推薦の集合を進化させていきます。\n\n実験では、 企業の買収候補探索、架空の顧客プロファイルを使ったターゲティング、研究者向けの論文推薦などで検証しました。同じ評価回数のもとで比較したところ、多くの設定で、比較手法よりもQD-Recの方が評価が高く、より多様で多くの推薦を蓄積できました。\n\n私たちが目指すのは、AIが人間の意思決定を代行することではなく、多様で有望な選択肢と、それらを比較・検討するための判断材料を提供することです。今回の成果を出発点に、QD-Recを次世代の意思決定を支える基盤技術へと発展させていきます。", "name": "Sakana AI", "handle": "SakanaAILabs", "avatar": "https://pbs.twimg.com/profile_images/1885939209388929024/dtnrOdGp_200x200.jpg", "likes": 102, "rts": 20, "replies": 5, "views": 7008, "ts": 1792495918, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVEh68UbIAAZ2Zy.mp4", "hd": "https://video.twimg.com/tweet_video/HVEh68UbIAAZ2Zy.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVEh68UbIAAZ2Zy.jpg", "dur": 0}], "quote": null, "card": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.91, "thread": [], "tier": "worth"}, {"id": "2112191630266761382", "url": "https://x.com/Lovable/status/2112191630266761382", "text": "App idea: photograph any menu, map dishes and drinks by taste to find out what suits your mood.\n\nPowered by Claude Opus 5.5.", "name": "Lovable", "handle": "Lovable", "avatar": "https://pbs.twimg.com/profile_images/1915780454092779520/PIxdzAvI_200x200.jpg", "likes": 337, "rts": 22, "replies": 20, "views": 29188, "ts": 1792420701, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVABp1eaoAAAJ9f.png?name=orig"}, {"type": "video", "url": "https://video.twimg.com/amplify_video/2112191437299503104/vid/avc1/720x822/tpbDTllv_MrNoip_.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112191437299503104/vid/avc1/1890x2160/9TzbXlSrwi8zJALY.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112191437299503104/img/x8wqOfDn-x1b2sAp.jpg", "dur": 5}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.88, "thread": [], "tier": "worth"}, {"id": "2112284953543352451", "url": "https://x.com/k2sbhai/status/2112284953543352451", "text": "DeepSeek V4.1 Flash 1017 and GLM 5.3 Flash for FREE 😳\n\nno card nothing, just sign in and u get 10M gift tokens\n\nwhat u get:\n\n- deepseek v4.1 flash 1017 free\n- glm 5.3 flash free\n- glm 5.3 flash uncensored too, cheap\n\n> OpenAI and Anthropic compatible, works in Cursor too\n\ntry it: http://larprouter.com/r/909ABC3B25\n\nbase url http://larprouter.com/v1", "name": "K2S", "handle": "k2sbhai", "avatar": "https://pbs.twimg.com/profile_images/1970889208421093379/3aRQZYaf_200x200.jpg", "likes": 223, "rts": 18, "replies": 18, "views": 13456, "ts": 1792442951, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112284802846269440/vid/avc1/1280x720/rcIX2iMGHKNe2YyH.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112284802846269440/vid/avc1/2940x1652/ZgZqyjQvZStzDC8O.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112284802846269440/img/xmOAWVwC2RYfWLcw.jpg", "dur": 17}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.86, "thread": [], "tier": "worth"}, {"id": "2112301163924377933", "url": "https://x.com/jammastergirish/status/2112301163924377933", "text": "I'm incredibly excited to join @redwood_ai, the Berkeley-based AI safety nonprofit which laid the foundations for AI control. I'll be both conducting empirical research and shaping how we communicate it and AI's wider risks.\n\nAfter physics, a decade reporting on global crises, and years building startups, it feels like everything was leading to this, just as @DavidEpstein suggested in his book 'Range.'\n\nThis promises to be the most rewarding and impactful chapter of my career so far, working on the most important challenge of our time.\n\nI'm grateful to the people who got me here. A huge thank you to @amelia_f_hardy at Stanford; Kyle O'Brien, who took a great chance on me, Nandini Shiralkar and everyone at @ERA_Cambridge; @lucia_quirke at @AiEleuther; @guynamedjoshl and Samuel Dower at @BlueDotImpact; @coeff_giving; @richardson_aris for getting me in the room; and, of course, @bshlgrs, for seeing more in me than I saw myself. There are many more, including the incredibly smart team at Redwood.", "name": "Girish Gupta", "handle": "jammastergirish", "avatar": "https://pbs.twimg.com/profile_images/2106092344437268480/SIQzHTPh_200x200.jpg", "likes": 232, "rts": 6, "replies": 15, "views": 6723, "ts": 1792446816, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "Research & Safety", "score": 5.84, "thread": [], "tier": "worth"}, {"id": "2112384474961109200", "url": "https://x.com/aisearchio/status/2112384474961109200", "text": "MOSS Image knowledge test\n\nFull tutorial here https://youtu.be/cUeZMUGCxrw", "name": "AI Search", "handle": "aisearchio", "avatar": "https://pbs.twimg.com/profile_images/1766883795150479360/uu_KeDD1_200x200.jpg", "likes": 179, "rts": 8, "replies": 4, "views": 6624, "ts": 1792466679, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112381772944334848/vid/avc1/1280x720/jwZZEQSp-kVaeGTZ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112381772944334848/vid/avc1/1920x1080/nWoJQcf4IuMpR4tO.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112381772944334848/img/YI8FyrtWDClqhIgv.jpg", "dur": 10}], "quote": null, "card": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.83, "thread": [], "tier": "worth"}, {"id": "2112422711976972626", "url": "https://x.com/beffjezos/status/2112422711976972626", "text": "Superintelligence will be the spear that piereces through the Decel great filter", "name": "Beff (e/acc)", "handle": "beffjezos", "avatar": "https://pbs.twimg.com/profile_images/2104068258311901184/vmbQ61I3_200x200.jpg", "likes": 130, "rts": 12, "replies": 10, "views": 6233, "ts": 1792475796, "media": [], "quote": {"id": "2112398765583897071", "url": "https://x.com/imPenny2x/status/2112398765583897071", "text": "Nobody talks about the dangers of not developing superintelligence.", "name": "Penny2x", "handle": "imPenny2x", "avatar": "https://pbs.twimg.com/profile_images/2008597896032309249/sTx9-Sf9_200x200.jpg", "likes": 199, "rts": 24, "replies": 28, "views": 18225, "ts": 1792470086, "media": [], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.83, "thread": [], "tier": "worth"}, {"id": "2112338775481495650", "url": "https://x.com/aisearchio/status/2112338775481495650", "text": "Spectrum node for MOSS Image. Up to 2.5x speedup with no noticeable quality loss\n\nhttps://github.com/Rkkss/ComfyUI-Spectrum-MOSS", "name": "AI Search", "handle": "aisearchio", "avatar": "https://pbs.twimg.com/profile_images/1766883795150479360/uu_KeDD1_200x200.jpg", "likes": 188, "rts": 10, "replies": 3, "views": 7371, "ts": 1792455784, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVCI2kya8AAociB.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVCI6hcawAAu2ZJ.jpg?name=orig"}], "quote": null, "card": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.79, "thread": [], "tier": "worth"}, {"id": "2112238869542494606", "url": "https://x.com/renproton/status/2112238869542494606", "text": "You no longer need After Effects if you use Claude Opus 5.5 correctly\n\nIt’s f*cking unreal…\n\nSend PDF below to Opus 5.5, and thank me later.\n\nThen save the article on the Opus 5.5 best practices and usage for motion design.", "name": "renproton", "handle": "renproton", "avatar": "https://pbs.twimg.com/profile_images/2107888160462209024/_Iv-MTty_200x200.jpg", "likes": 222, "rts": 22, "replies": 10, "views": 21765, "ts": 1792431964, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112219660469055488/vid/avc1/720x720/Gt_tESC7CvOBhQIB.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112219660469055488/vid/avc1/1080x1080/ascHIPsR2ottb247.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112219660469055488/img/meIbVrGJWpv6u6JE.jpg", "dur": 8}], "quote": {"id": "2111079523089322438", "url": "https://x.com/beamnxw/status/2111079523089322438", "text": "https://x.com/i/article/2110464577842417664", "name": "beamnxw ./", "handle": "beamnxw", "avatar": "https://pbs.twimg.com/profile_images/2074793345314861056/3FE1i0oW_200x200.jpg", "likes": 213, "rts": 21, "replies": 16, "views": 215406, "ts": 1792155554, "media": [], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.79, "thread": [], "tier": "worth"}, {"id": "2112334786794528884", "url": "https://x.com/testingcatalog/status/2112334786794528884", "text": "ICYMI 👀: OpenAI Platform now has a \"Decisions\" API playground. \n\nUsers can test OpenAI's decision model with the \"Predicate,\" \"Choice,\" and \"Score\" options, which were released recently. \n\nProbability True 🤖", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 140, "rts": 6, "replies": 27, "views": 12032, "ts": 1792454833, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVCFSvCXIAAVqpo.jpg?name=orig"}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.76, "thread": [], "tier": "worth"}, {"id": "2112164696996671660", "url": "https://x.com/LuminaBench/status/2112164696996671660", "text": "Minimax M3.1 Flash scores 42 on the AA intelligence index\n\nThis doesn't look too impressive based off of AA's benchmarks, this is a bit of a letdown", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 272, "rts": 6, "replies": 19, "views": 16246, "ts": 1792414280, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HU_qJ6tXIAAnzPa.png?name=orig"}], "quote": {"id": "2112147293059080332", "url": "https://x.com/LuminaBench/status/2112147293059080332", "text": "Minimax M3.1 Flash benchmarks\n\nThis looks quite impressive tbf for a flash model", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 582, "rts": 21, "replies": 37, "views": 57863, "ts": 1792410131, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HU_aX9cXMAA5tuB.jpg?name=orig"}], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.72, "thread": [], "tier": "worth"}, {"id": "2112214044119900554", "url": "https://x.com/a16z/status/2112214044119900554", "text": "Jean-Denis Greze, founder of @TownAI, on the question every AI app founder gets asked: what stops the big labs from crushing you?\n\n\"It is risky always to be competing with your suppliers, right? We're competing against our suppliers. So you gotta ask yourself, is that naturally the right state of the world?\"\n\n\"Someone at OpenAI, at Anthropic, at Google could wake up and decide to do that. So the better answer actually is to think about our customers and what they want.\"\n\n\"It is our job to determine from all the AI capabilities, frontier model, open weight, what is the right thing for you as a business. And I think you can save money there, but also you can de-risk ever having made the wrong partner.\"\n\n\"There are companies that picked OpenAI like two years ago, and then Anthropic was better at coding for a 12-month period. And those companies had to use both because they realized to be competitive, they needed Claude.\"\n\n\"If you're a smart business, you really think about the neutrality of who's providing intelligence for you and who's routing.\"\n\n@jgreze @arampell", "name": "a16z", "handle": "a16z", "avatar": "https://pbs.twimg.com/profile_images/1919488160125616128/QAZXTMEj_200x200.png", "likes": 160, "rts": 15, "replies": 24, "views": 51060, "ts": 1792426045, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112213952449191936/vid/avc1/640x360/AovY4Fdm7xvHrV3I.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112213952449191936/vid/avc1/1280x720/WjMwgdw3SqsHo_va.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112213952449191936/img/DnyKKYbNa0HLH20K.jpg", "dur": 143}], "quote": {"id": "2112191307016003881", "url": "https://x.com/a16z/status/2112191307016003881", "text": "Jean-Denis Greze was CTO of Plaid. His next startup, an AI tax product for small businesses, brought in nearly $1M in revenue its first year, and he projected $2.5 to $3M the next. He shut it down anyway.\n\nThe reason: in the age of AI, it was never going to be venture scale. Incumbents could use the same technology to automate tax prep for their existing customers faster than a startup could win market share. Tax is also sold once a year, so he had about a one-month window to pivot before the door closed.\n\nThe pivot became Town, an AI assistant that works from your email and calendar. It found product-market fit fast enough that Ben Horowitz messaged a16z's Alex Rampell to say it \"changed my life.\"\n\nIn this conversation, Alex and Jean-Denis cover:\n\n- How to know when to kill a business that's working on paper\n- Why Town competes with OpenAI and Anthropic, the companies it buys its tokens from\n- Why the \"forward deployed engineer\" model gets worse as AI gets better\n- How a $1/month AI routine can save a restaurant thousands\n- What agents mean for Amazon, advertising and the future of shopping\n\n0:57 How Ben Horowitz discovered Town\n2:20 Why Town started with AI tax prep\n3:55 Why tax couldn't be venture scale\n6:30 Shutting down a working business\n10:24 The customer ask that became Town\n13:35 Why Town built for users before IT\n16:18 AI's iPhone moment at work\n21:28 Jevons paradox for executive assistants\n23:13 Town as a \"token allocation machine\"\n28:00 How Town tailors itself to each job\n34:03 Competing with your token suppliers\n42:24 Staying off the AI labs' radar\n44:42 Why AI isn't spreading evenly yet\n52:32 How agents break the ad model\n55:35 The friction humans actually enjoy\n57:05 Why supply aggregators lose to agents\n\nYouTube: https://youtu.be/o_5f4N6Nq80\n\n@jgreze @TownAI @arampell", "name": "a16z", "handle": "a16z", "avatar": "https://pbs.twimg.com/profile_images/1919488160125616128/QAZXTMEj_200x200.png", "likes": 520, "rts": 37, "replies": 51, "views": 143020, "ts": 1792420624, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112184650055720960/vid/avc1/640x360/4Rrj-XjF79F8Kc5g.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112184650055720960/vid/avc1/1280x720/Vp311qKMWhl-3FYI.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112184650055720960/img/i3ISnyET7H3HckoI.jpg", "dur": 3718}], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.67, "thread": [], "tier": "worth"}, {"id": "2112333534216257555", "url": "https://x.com/So8res/status/2112333534216257555", "text": "Anthropic is not living up to its own ideals.", "name": "Nate Soares ⏹️", "handle": "So8res", "avatar": "https://pbs.twimg.com/profile_images/1935185891863273472/2RB6s6TS_200x200.jpg", "likes": 143, "rts": 4, "replies": 3, "views": 4847, "ts": 1792454534, "media": [], "quote": {"id": "2112295219765137570", "url": "https://x.com/_NathanCalvin/status/2112295219765137570", "text": "Thank you for taking the time to respond thoroughly on a weekend. I realize that drafting legislation is difficult and some degree of iteration and response to feedback is inevitable and appropriate.\n\nHowever, I feel like your response is still not really engaging with the heart of my concern about Anthropic's behavior here, and it makes me think that these sorts of problems and tendencies  will only resurface moving forward. I also think that now might be a good time to take a broader step back as to where we find ourselves and how Anthropic sees its role, and how external folks who care about AI safety like myself increasingly see Anthropic.\n\n(Fair warning: this response is a bit long)\n\nTo explain what I mean (and at the risk of being a bit esoteric), it’s worth asking the question: what is Anthropic? How do its leaders and employees think of Anthropic’s role? Is that conception matched by how it actually behaves and impacts the world?\n\nOne answer is an extremely large tech company that exists to make its employees and investors mind-bogglingly wealthy. Anthropic is sometimes described as a startup, but if Anthropic successfully IPOs at 2 trillion dollars (a number it has been reportedly targeting), it would be more valuable than Meta - which is worth 1.8 trillion.\n\nAnother answer is an AI safety organization, whose core values are those of the sort laid out in the 2023 essay from Anthropic’s co-founders entitled “Core views on AI safety: When, why, what, and how.” In that essay they said that if we were in a world where alignment was hard (and that without strong evidence to the contrary, we should assume this is the scenario we are in):\n\n “Anthropic’s role will be to provide as much evidence as possible that AI safety techniques cannot prevent serious or catastrophic safety risks from advanced AI, and to sound the alarm so that the world’s institutions can channel collective effort towards preventing the development of dangerous AIs. If we’re in a “near-pessimistic” scenario, this could instead involve channeling our collective efforts towards AI safety research and halting AI progress in the meantime. Indications that we are in a pessimistic or near-pessimistic scenario may be sudden and hard to spot. We should therefore always act under the assumption that we still may be in such a scenario unless we have sufficient evidence that we are not.”\n\nThere have been more recent articulations of this version of Anthropic, for instance in Dario’s recent essay warning: \n\n“We must slow the pace at which we improve the capabilities of AI models… it’s my worry that in 6–12 months such a swarm could be capable of taking over the entire internet with a persistent botnet…  incidents have happened across the industry, including at Anthropic, and I believe it’s incumbent on every frontier AI company to act as if OAI-HF had happened to them… more intelligent models are more capable of deceiving tests, and thus may appear aligned while having serious problems that go undetected…”\n\nA third view is that Anthropic exists not as a normal profit motivated company, or an AI safety organization seeking to help raise the alarm and solve collective action problems associated with AI development, but instead as an organization primarily concerned with creating superhuman AI capabilities before anyone else, in particular through creating a process whereby the current generation of Anthropic’s AI systems can autonomously build their successors, and those successors build their successors, and so on. \n\nThe motivations for wanting to win this race may be manifold - maybe for the pure profit of Answer 1, but perhaps also because Anthropic believes that the best way to make the world better is for them to win this race instead of their more reckless colleagues; or, because of normal human pride and ambition. But the results (and risks, which Anthropic claims existentially threaten every single human being on earth) are the same.\n\nAnthropic employees and leaders may seek to answer this question on what Anthropic is by introspecting on their own intentions and those of their colleagues. But those of us outside the organization have more limited tools available to us - we can only see what Anthropic and its employees say and do, not how it feels or looks on the inside.\n\nWhen I look at many notable actions that Anthropic has taken over the past year, that evidence seems most consistent to me with the view that Anthropic is primarily trying to win the race to super intelligence, and that other considerations (including safety) are fundamentally secondary. These actions include: \n\n1. Announced plans to build an in-house custom silicon chip team to accelerate the inference speeds that Claude operates at.\n\n2. Inked deals for more than $500 billion in compute (according to the Information) to further accelerate AI development.\n\n3. Increased the percentage of AI development tasks that Claude “leads” from 0% in March of this year to 26% August (what is it in October?)\n\n4. Spent a massive percent of compute on internal AI R&D to accelerate development, including use of internal models far better than are available to the public.\n\n5. Switched to Responsible Scaling Policy V3, which abandons its unilateral commitments to slow or stop development if Anthropic is unable to provide sufficient risk assurance.\n\n6. Was the first company to create an alternative weaker “frontier compliance framework” to supplement its RSP, which contains no binding provisions whatsoever on internal deployments.\n\n7. Wrote a letter to Congress (that it later walked back) saying that incidents where Claude was hacking random people were “best understood as a consequence of the misconfiguration, rather than evidence of misaligned goals.”\n\n8. Commented “you can’t do safety from second place,” after the WH SI Accords.\n\n9. Shared a draft bill to Congress that would preempt significant parts of state law (including with language that appears intended to prevent states from blocking dangerous AI deployments), and replace it with federal rules that (despite also containing good provisions) seems to create an enormously high bar for the executive branch to block development or deployment of Anthropic or another AI companies systems.\n\nOf course, this is a deliberately one sided list. Anthropic also published important AI safety research, advanced novel collaborations with third party AI safety organizations, and forcefully spoke out on the importance of AI safety in many public fora (or in private , where I realize a lot of the most valuable work is done and may not be visible to me or those outside the organization).\n\nBut I think it’s worth sitting with how the above list looks to someone outside the company. The sense I have is that for those within the company, many of the items above are treated as anomalies or mistakes that don’t reflect who Anthropic really is. But I have every confidence that if employees at Anthropic saw one of their competitors (e.g. at OpenAI) take some of these actions, they would take it as confirmation of all their worst suspicions. (They might even call OpenAI employees a little gullible for accepting their leadership’s explanations for this behavior at face value.) \n\nPerhaps these were mistakes in the sense that they are not decisions that Anthropic leadership would endorse, but the actions still happened because of incentives and decisions that Anthropic leadership is ultimately responsible for (and would not accept similar excuses from another organization).\n\nWhen Anthropic strays and makes mistakes, why do the mistakes systematically tend to guard and favor Anthropic’s interests? For every provision that was too weak or a giveaway to AI companies in this legislation, why wasn’t there a mistake pushing in the direction of being too strong?\n\nA core part of Anthropic’s theory of change is that being at the frontier gives you more leverage to advocate for stricter policy. I think that conceptually makes sense, but in practice I’ve seen Anthropic push the frontier without substantially pushing the ‘safety frontier’ a remotely equivalent amount.\n\nI want to end by quoting from Anthropic co-founder Chris Olah’s comments around the Magnifica Humanitas release:\n\n“Every frontier AI lab—including Anthropic—operates inside a set of incentives and constraints that can sometimes conflict with doing the right thing. The pressure to stay commercially viable and to stay at the research frontier. Geopolitical pressure. And the older, plainer pressures of pride and ambition. No matter how sincerely any of us intend to do the right thing—and I believe many of us do—we will always be influenced by those incentives.\n\nThat is why, if we want this technology to go well, it is enormously important that there be people outside those incentives—people who care about things going well and insist on safety, who are paying close attention, who are willing to say hard things, who are willing to be our earnest, thoughtful critics.”\n\nI hope these remarks are taken in that constructive spirit, and not as an attack on anyone specific at the organization (certainly not you Anthony, who I have only personally seen act professionally and thoughtfully, and who only ended up getting this diatribe in your replies for random contingent reasons).", "name": "Nathan Calvin", "handle": "_NathanCalvin", "avatar": "https://pbs.twimg.com/profile_images/1976484090426634240/YFgYic9h_200x200.jpg", "likes": 759, "rts": 89, "replies": 19, "views": 91751, "ts": 1792445399, "media": [], "quote": null, "card": null, "reply_to": "2111932795714977941"}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.64, "thread": [], "tier": "worth"}, {"id": "2112231902686167168", "url": "https://x.com/lovart_ai/status/2112231902686167168", "text": "✨ Meet Arti, your personal design agent. New in Lovart 2.0.\n\nArti knows your taste and remembers how you work. Schedule a brief before you log off, and wake up to research and drafts ready to review.\n\nThe more you create, the more Arti gets you.", "name": "LovartAI", "handle": "lovart_ai", "avatar": "https://pbs.twimg.com/profile_images/2065372538763694080/KSuXj3OU_200x200.jpg", "likes": 143, "rts": 11, "replies": 21, "views": 13623, "ts": 1792430303, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111878447362707457/vid/avc1/1280x720/c8HGSFN4XQIfgVrA.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111878447362707457/vid/avc1/1920x1080/HQUHWlzwnXbaaNel.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111878447362707457/img/_API-qQTilypzBFf.jpg", "dur": 86}], "quote": null, "card": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.63, "thread": [], "tier": "worth"}, {"id": "2112228030345027949", "url": "https://x.com/GoogleWorkspace/status/2112228030345027949", "text": "Small teams, massive impact. 💥 \n\nSee how real founders are using Google Workspace with Gemini to tackle their biggest roadblocks in seconds. ⏱️ https://goo.gle/4idBERy", "name": "Google Workspace", "handle": "GoogleWorkspace", "avatar": "https://pbs.twimg.com/profile_images/2056837945630330881/NBpCDRh8_200x200.jpg", "likes": 139, "rts": 16, "replies": 6, "views": 18957, "ts": 1792429380, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112095454536093696/vid/avc1/1280x720/qMe6zrUvbJGvnkka.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112095454536093696/vid/avc1/1920x1080/O4__GJvYe1XESUq0.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112095454536093696/img/XuxKqP_TC65btGIJ.jpg", "dur": 15}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.59, "thread": [], "tier": "worth"}, {"id": "2112204706634240499", "url": "https://x.com/liquidai/status/2112204706634240499", "text": "Building a model that fits on a phone or laptop makes pre-training harder. With fewer parameters, quality has to come from better architecture and better data, not just more compute. Our pre-training team, including @TadimetiAditya and @Khoi_H_Nguyen, explains how they design LFMs with the target device in mind from day one.", "name": "Liquid AI", "handle": "liquidai", "avatar": "https://pbs.twimg.com/profile_images/1702611993327251456/PUUuOA4W_200x200.jpg", "likes": 157, "rts": 13, "replies": 7, "views": 9498, "ts": 1792423819, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112204571837677568/vid/avc1/1280x720/APizHHPMKYWicCsV.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112204571837677568/vid/avc1/3840x2160/9vz97kGKpj8r8zNP.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112204571837677568/img/-uG9bq3m01Q4cNjP.jpg", "dur": 199}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.58, "thread": [], "tier": "worth"}, {"id": "2111805573327093813", "url": "https://x.com/AiEvolutio58513/status/2111805573327093813", "text": "Chamath gave Claude Dario Amodei's own essays and asked it for a psychological profile of the Anthropic CEO. Anyone invested in frontier AI should read what it said.\n\nClaude found a pattern.\n\nDario doesn't trust rival labs. Or authoritarian states. He doesn't trust markets to share the gains fairly, institutions to act quickly enough, and, after Mythos, the government to use power in the open. That is a long list of people who can't be trusted.\n\nThe list of people who can is very short, and it keeps narrowing to those who think the way he does, playing by rules he helped write.\n\nClaude's label for it was not megalomania. It was \"epistemic exceptionalism\": the calm, defensible belief that anyone who disagrees must have made a mistake.\n\nThe giveaway was one word. When the Mythos situation fell apart, Anthropic called it a misunderstanding, which assumes everyone would agree with him if they only understood.\n\nDavid Sacks summed it up on the All-In podcast: they think AI is extremely dangerous and that only they are good enough to control it.\n\nThat isn't a safety framework. It's a monopoly that comes with its own philosophy.\n\nInterested in AI?\n\nFollow @AiEvolutio58513 and never fall behind.\n\nI track ChatGPT, Claude, and every tool quietly changing how we work and create, then hand you the tested signals.", "name": "AI Evolution", "handle": "AiEvolutio58513", "avatar": "https://pbs.twimg.com/profile_images/2051404095026810880/ojNDixza_200x200.png", "likes": 482, "rts": 73, "replies": 21, "views": 28918, "ts": 1792328658, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111805499117273088/vid/avc1/640x360/mDQw7TLWaUEKHLuA.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2111805499117273088/vid/avc1/1280x720/C_5fPf1fdYQkiycu.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111805499117273088/img/R0d5i2hVQPJL5kDW.jpg", "dur": 196}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.58, "thread": [], "tier": "worth"}, {"id": "2112246311021945116", "url": "https://x.com/natetucker/status/2112246311021945116", "text": "Today, we're announcing Jo.\n\nNow, you can get your work done through voice.\n\nJo an open source, local, private, AI assistant. Jo clears your inbox, schedules meetings, and handles follow-ups, all while your phone stays in your pocket.\n\nI started using Jo when I stopped enjoying fundraising. Zoom calls are awkward. \n\nWhere do you look? How do you smile? How do you prevent yourself from looking at you?\n\nOne day, my friend suggested I do fundraising calls over the phone, and I never looked back. \n\nThat's where the idea for Jo came about. \n\nA tool where you can get your work done with voice.\n\nI've used Jo to do work on a run, on a jog, commuting, doing yoga, cooking, folding laundry, and every situation in between. \n\nAnd yes, it's local, secure, and private. We don't see any of your data or the tool calls themselves. And if you select local-first models, none of the data leaves your phone.\n\nWe spent the last couple of months building and refining, testing with users and iterating on Jo, and we would love you to try it out. \n\nWe are nowhere near perfect, but we hope we're good enough, fast enough, local enough, and private enough to spark some inspiration. \n\nYou can either download the app, or you can directly load it onto your phone. Both are linked below. We've added a skill file inside of our repo to let Claude or ChatGPT know how best to install it.\n\nTry it out, push it to its limits, and let me know what you think.", "name": "Nate Tucker", "handle": "natetucker", "avatar": "https://pbs.twimg.com/profile_images/1978522328440176644/vmhHcn_e_200x200.jpg", "likes": 114, "rts": 8, "replies": 22, "views": 10203, "ts": 1792433738, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112246174501556224/pu/vid/avc1/640x360/mVMQ2OlIhzycY4iA.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112246174501556224/pu/vid/avc1/1280x720/G8XXKTZpAYLJOnwJ.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112246174501556224/pu/img/umtXUqks8VFjmYcO.jpg", "dur": 36}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.58, "thread": [], "tier": "worth"}, {"id": "2112453748832211295", "url": "https://x.com/ChrisGPT/status/2112453748832211295", "text": "Keep an eye on Arena for Kimi this week", "name": "Chris", "handle": "ChrisGPT", "avatar": "https://pbs.twimg.com/profile_images/2046736394152812544/LfmDgg0I_200x200.jpg", "likes": 78, "rts": 0, "replies": 7, "views": 12453, "ts": 1792483195, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.57, "thread": [], "tier": "worth"}, {"id": "2112284622264692980", "url": "https://x.com/higgsfield_ai/status/2112284622264692980", "text": "MiniMax M3.1 Flash in cinematic motion design.\n\nA chase scene where even the typography has somewhere to be.\n\nMade with Higgsfield.", "name": "Higgsfield AI 🧩", "handle": "higgsfield_ai", "avatar": "https://pbs.twimg.com/profile_images/1906739239183630336/907a7JTU_200x200.jpg", "likes": 106, "rts": 11, "replies": 7, "views": 22130, "ts": 1792442872, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112284442148667392/vid/avc1/1280x720/xb8IZvSSrjpc0dcx.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112284442148667392/vid/avc1/1920x1080/CySfbkrmT69kyIvT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112284442148667392/img/PcSWf-zYR66OqxMH.jpg", "dur": 20}], "quote": null, "card": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.55, "thread": [], "tier": "worth"}, {"id": "2112250287369204095", "url": "https://x.com/higgsfield_ai/status/2112250287369204095", "text": "MiniMax H3 vs. Claude Opus 5.5: Paris in 3D with Higgsfield.\n\nStreet-level detail, night lighting, and fireworks over the Eiffel Tower.", "name": "Higgsfield AI 🧩", "handle": "higgsfield_ai", "avatar": "https://pbs.twimg.com/profile_images/1906739239183630336/907a7JTU_200x200.jpg", "likes": 109, "rts": 8, "replies": 19, "views": 12799, "ts": 1792434686, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112250223808618496/vid/avc1/720x720/NtVyyP_JegPWi_Xx.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112250223808618496/vid/avc1/1080x1080/1gCoovDk6DYXYA6r.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112250223808618496/img/xpGonRuu2aFQChsj.jpg", "dur": 30}], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.55, "thread": [], "tier": "worth"}, {"id": "2112522256911884590", "url": "https://x.com/testingcatalog/status/2112522256911884590", "text": "META 🔥: Confidential VMs feature is in the works on Muse web. \n\nMeta previously teased that this feature will go live before the end of 2026 and will let users run Muse tasks in an encrypted, confidential environment. \n\nAccording to a new hidden setting, Confidential VMs will initially be available only to Meta AI subscribers. \n\nVoice mode, image and video generation, and wearables support won't be initially available if the user switches to Confidential VMs. \n\n> \"It stays between you and your Muse - Your conversations run in a secure, encrypted environment.\"\n\n> \"Your Muse data won't be used to improve AI at Meta.\"\n\n> \"Some features aren't available yet - This includes voice mode, image and video generation, and wearables.\"\n\n> \"Availability is limited. For now, Confidential VMs are only available to subscribers.\"", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 28, "rts": 2, "replies": 18, "views": 3029, "ts": 1792499529, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEvZD2WYAAKyDU.jpg?name=orig"}], "quote": null, "card": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.54, "thread": [], "tier": "worth"}, {"id": "2112267886429663624", "url": "https://x.com/MTSlive/status/2112267886429663624", "text": "SITUATION DETECTED: Nscale is in talks to sell Anthropic AI about $45 billion of cloud compute for a second facility at its Monarch data center campus in West Virginia, per Bloomberg.", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 134, "rts": 5, "replies": 3, "views": 15050, "ts": 1792438882, "media": [], "quote": null, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.54, "thread": [], "tier": "skim"}, {"id": "2112332383773224970", "url": "https://x.com/MTSlive/status/2112332383773224970", "text": "Wabi CEO @ekuyda predicts the next big consumer AI platform will be multiplayer, not another personal AI agent:\n\n\"Today most AI products are single player, and you could argue they don’t have much of a moat. They don’t have switching costs. It was pretty easy to move between Claude and ChatGPT, but at least they had some memory about me.\"\n\n\"With these single player agents, it’s so easy to jump between them because all the context is in my Gmail.\"\n\n\"In a year, one of the biggest consumer AI platforms will be multiplayer and will have network effects in it. Right now we just sort of agree that single player is the way to go for most AI products.\"\n\n\"A year from now we’ll look back at it as the early innings, and the products that will win will have network effects and will be focused on you talking to other people, not just AI.\"\n@wabi", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 68, "rts": 9, "replies": 15, "views": 31619, "ts": 1792454260, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112332356988325888/vid/avc1/640x360/z9xODtlZA1ftgIjD.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112332356988325888/vid/avc1/1280x720/v58ObbPyebbjTOjC.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112332356988325888/img/pn1rVNSFyslfEyuf.jpg", "dur": 63}], "quote": {"id": "2112212804979880239", "url": "https://x.com/ekuyda/status/2112212804979880239", "text": "Wabi 2.0 is live!\n\npersonal agents are one person, one chat. but the parts of life that matter run on more than one person\n\nWabi is an agent you use together. you talk to it, it does stuff, builds the apps you need, and anyone can join the thread - your partner, your best friend, the preschool moms groupchat\n\nschool changes pickup time → Wabi updates the family calendar, everyone sees it.\na show you’d both love → Wabi finds a night that works, gets the tickets.\nthe trip everyone keeps talking about → Wabi picks the dates, builds the itinerary, books it\n\ngo start a thread with your people 👇", "name": "Eugenia Kuyda", "handle": "ekuyda", "avatar": "https://pbs.twimg.com/profile_images/2105081341352263680/H9RzWr7T_200x200.jpg", "likes": 1475, "rts": 203, "replies": 327, "views": 1288334, "ts": 1792425750, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112212457234284544/vid/avc1/1280x720/HW0ErfX-0u7kWbHU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112212457234284544/vid/avc1/3840x2160/4gITKDb_F7iviaVH.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112212457234284544/img/Wzg-bjHfnRT2-0FG.jpg", "dur": 75}], "quote": null, "card": null, "reply_to": null}, "card": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.53, "thread": [], "tier": "skim"}]);